pub fn mlp_inference(x: &[i16]) -> Eval {
    const SH: usize = P1_B3.len();
    const ADJ_OUT: usize = A_B2.len();
    let mut cat = [0.0f32; SH*2 + ADJ_OUT];
    shared1_inference(&x[..Board::FN], &mut cat[..SH]);
    shared2_inference(&x[Board::FN..Board::FN2], &mut cat[SH..SH*2]);
    adj_inference(&x[Board::FN2..], &mut cat[SH*2..]);
    head_inference(&cat)
}

fn layer(x: &[f32], w: &[f32], b: &[f32], y: &mut [f32], relu: bool) {
    debug_assert_eq!(w.len(), x.len() * y.len());
    debug_assert_eq!(b.len(), y.len());
    for j in 0..y.len() {
        y[j] = b[j];
        for i in 0..x.len() {
            y[j] += w[j * x.len() + i] * x[i];
        }
        if relu {
            y[j] = y[j].max(0.0);
        }
    }
}

fn shared1_inference(x: &[i16], y: &mut [f32]) {
    let mut x0 = [0.0; Board::FN];
    for i in 0..Board::FN { x0[i] = x[i] as f32; }
    let mut x1 = [0.0; P1_B1.len()];
    layer(&x0, P1_W01.as_flattened(), &P1_B1, &mut x1, true);
    let mut x2 = [0.0; P1_B2.len()];
    layer(&x1, P1_W12.as_flattened(), &P1_B2, &mut x2, true);
    layer(&x2, P1_W23.as_flattened(), &P1_B3, y, true);
}

fn shared2_inference(x: &[i16], y: &mut [f32]) {
    let mut x0 = [0.0; Board::FN];
    for i in 0..Board::FN { x0[i] = x[i] as f32; }
    let mut x1 = [0.0; P2_B1.len()];
    layer(&x0, P2_W01.as_flattened(), &P2_B1, &mut x1, true);
    let mut x2 = [0.0; P2_B2.len()];
    layer(&x1, P2_W12.as_flattened(), &P2_B2, &mut x2, true);
    layer(&x2, P2_W23.as_flattened(), &P2_B3, y, true);
}

fn adj_inference(x: &[i16], y: &mut [f32]) {
    let mut x0 = [0.0; Board::ADJ_SIZE];
    for i in 0..Board::ADJ_SIZE { x0[i] = x[i] as f32; }
    let mut x1 = [0.0; A_B1.len()];
    layer(&x0, A_W01.as_flattened(), &A_B1, &mut x1, true);
    let mut x2 = [0.0; A_B2.len()];
    layer(&x1, A_W12.as_flattened(), &A_B2, &mut x2, true);
    layer(&x2, A_W23.as_flattened(), &A_B3, y, true);
}

fn softsign(x: f32) -> f32 {
    x / (1.0 + x.abs())
}

fn head_inference(xin: &[f32]) -> Eval {
    let mut x1 = [0.0; F_B1.len()];
    layer(&xin, F_W01.as_flattened(), &F_B1, &mut x1, true);
    let mut x2 = [0.0; F_B2.len()];
    layer(&x1, F_W12.as_flattened(), &F_B2, &mut x2, true);
    let mut x3 = [0.0; F_B3.len()];
    layer(&x2, F_W23.as_flattened(), &F_B3, &mut x3, true);
    let mut x4 = [0.0; F_B4.len()];
    layer(&x3, F_W34.as_flattened(), &F_B4, &mut x4, false);
    let logit = x4[0];
    let output = (softsign(logit) * 1.5).clamp(-1.0, 1.0) * 6000.0;
    output.round() as Eval
}

